WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_b_reverse'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '基础反求', 'kp-eng-b-reverse', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基础反求问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "给出合作结果，倒推某个人的单独效率或单独完工时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是合作完工的逆向题。已知“甲乙合作需 12 天完成”，又已知“甲单独做需 20 天”，问“乙单独做需要几天？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "依然是赋值法，只是中间做一次减法："}]}, {"type": "katexBlock", "attrs": {"content": "P_B = P_{合作} - P_A \\quad \\Rightarrow \\quad T_B = \\frac{W}{P_{合作} - P_A}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到合作时间与甲单独时间] --> B[取两者的最小公倍数赋给 W]\nB --> C[算出合作总效率 P合 和 甲效率 Pa]\nC --> D[用减法算出乙的效率: Pb = P合 - Pa]\nD --> E[用 W 除以 Pb 得到乙的单独完工时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 一项工程，甲乙合作需要 12 天完工。已知甲单独完成需要 20 天。问乙单独完成这项工程需要多少天？选项：A. 15  B. 24  C. 30  D. 40"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：找 12（合作）和 20（甲单干）的公倍数。12=4×3，20=4×5。最小公倍数 = 4×3×5 = 60。设 W = 60。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出效率：P合 = 60 ÷ 12 = 5。P甲 = 60 ÷ 20 = 3。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "做减法求乙：P乙 = P合 - P甲 = 5 - 3 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "反求乙的时间：T乙 = W ÷ P乙 = 60 ÷ 2 = 30 天。选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "瞎找公倍数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有些题目给的时间是分数，比如“甲乙合作需要 4.5 天”。这种时候千万别傻傻去算 4.5 的公倍数。一定要先把 4.5 化为 9/2，然后找分子（9 和其他时间）的公倍数赋给 W！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "反求问题的核心在于“剥离法”。只要牢记 P总 - P已知 = P未知，不管题目怎么绕，只要把所有已知时间全部扔进公倍数锅里，效率自然水落石出。"}]}]}$$ AS jsonb), NULL, '基础反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "基础反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_b_reverse", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
